import sympy

def f(n):
    return n**4 - 360*n**2 + 400

def is_prime(num):
    return sympy.isprime(num)

prime_sum = 0
for n in range(-100, 101):
    value = f(n)
    if value > 0 and is_prime(value):
        prime_sum += value

print(prime_sum)
```
